"use client";

import {
  type CSSProperties,
  type HTMLAttributes,
  type KeyboardEvent,
  type ReactNode,
  useId,
  useMemo,
  useState,
} from "react";
import { chartPath, scalePoints } from "../utils/chart";
import { cx } from "../utils/cx";
import type { BarDatum } from "./bar-chart";

export type LineChartProps = Omit<HTMLAttributes<HTMLElement>, "title"> & {
  data: BarDatum[];
  title: ReactNode;
  caption?: ReactNode;
  format?: Intl.NumberFormatOptions;
  locale?: string;
  /** Plot height. Default 9rem. */
  height?: string;
  /** Fill under the line. Default true. */
  area?: boolean;
  /** Smooth (monotone) or straight segments. Default smooth. */
  curve?: "smooth" | "linear";
  empty?: ReactNode;
};

const W = 600;
const H = 120;

/**
 * A line (or area) chart in the studio's chart language: a hairline grid, the line drawing itself in once, and a marker
 * that glides between points as the pointer or keyboard focus moves. One tab stop; arrows move between points, and
 * each point is announced as "label: value".
 */
export function LineChart({
  data,
  title,
  caption,
  format,
  locale,
  height,
  area = true,
  curve = "smooth",
  empty = "No data for this period.",
  className,
  style,
  ...rest
}: LineChartProps) {
  const [active, setActive] = useState<number | null>(null);
  const [focusIndex, setFocusIndex] = useState(Math.max(0, data.length - 1));
  const fmt = useMemo(() => new Intl.NumberFormat(locale, format), [locale, format]);
  const gradient = useId();
  const points = useMemo(
    () =>
      scalePoints(
        data.map((d) => d.value),
        W,
        H,
        6,
        0,
      ),
    [data],
  );
  const line = useMemo(() => chartPath(points, curve === "smooth"), [points, curve]);
  const fill = `${line}L${W} ${H}L0 ${H}Z`;
  const shown = active === null ? null : data[active];
  const at = active ?? focusIndex;
  const marker = points[at];
  const hasData = data.some((d) => d.value > 0);

  const onKey = (e: KeyboardEvent<HTMLDivElement>) => {
    const n = data.length;
    const keys: Record<string, number> = { ArrowRight: focusIndex + 1, ArrowLeft: focusIndex - 1, Home: 0, End: n - 1 };
    if (!(e.key in keys)) return;
    e.preventDefault();
    const to = Math.max(0, Math.min(n - 1, keys[e.key] ?? 0));
    setFocusIndex(to);
    setActive(to);
    e.currentTarget.querySelectorAll<HTMLButtonElement>(".hm-line-hit")[to]?.focus();
  };

  return (
    <figure {...rest} className={cx("hm-line-chart", className)} style={{ ...style, "--_h": height } as CSSProperties}>
      <figcaption className="hm-bar-chart-head">
        <span className="hm-bar-chart-title">{title}</span>
        <span className="hm-bar-chart-caption" aria-live="polite">
          {shown ? `${shown.label} · ${fmt.format(shown.value)}` : caption}
        </span>
      </figcaption>
      {hasData ? (
        <>
          <div className="hm-line-plot">
            <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" aria-hidden="true">
              <defs>
                <linearGradient id={gradient} x1="0" y1="0" x2="0" y2="1">
                  <stop offset="0" stopColor="var(--hm-accent)" stopOpacity="0.28" />
                  <stop offset="1" stopColor="var(--hm-accent)" stopOpacity="0" />
                </linearGradient>
              </defs>
              {[0.25, 0.5, 0.75].map((g) => (
                <path key={g} className="hm-line-grid" d={`M0 ${g * H}H${W}`} />
              ))}
              <g className="hm-line-reveal">
                {area ? <path className="hm-line-area" d={fill} fill={`url(#${gradient})`} /> : null}
                <path className="hm-line-stroke" d={line} />
              </g>
            </svg>
            {marker ? (
              <>
                <span
                  className="hm-line-rule"
                  data-on={active !== null ? "" : undefined}
                  style={{ left: `${(marker[0] / W) * 100}%` }}
                />
                <span
                  className="hm-line-dot"
                  data-on={active !== null ? "" : undefined}
                  style={{ left: `${(marker[0] / W) * 100}%`, top: `${(marker[1] / H) * 100}%` }}
                />
              </>
            ) : null}
            <div
              className="hm-line-hits"
              role="group"
              aria-label={typeof title === "string" ? title : undefined}
              onPointerLeave={() => setActive(null)}
              onKeyDown={onKey}
            >
              {data.map((d, i) => (
                <button
                  key={d.label}
                  type="button"
                  className="hm-line-hit"
                  tabIndex={i === focusIndex ? 0 : -1}
                  aria-label={`${d.label}: ${fmt.format(d.value)}`}
                  onPointerEnter={() => setActive(i)}
                  onFocus={() => {
                    setFocusIndex(i);
                    setActive(i);
                  }}
                  onBlur={() => setActive(null)}
                />
              ))}
            </div>
          </div>
          <div className="hm-bar-axis" aria-hidden="true">
            <span>{data[0]?.label}</span>
            <span>{data[data.length - 1]?.label}</span>
          </div>
        </>
      ) : (
        <p className="hm-empty">{empty}</p>
      )}
    </figure>
  );
}
